/**
 * Slices kept before the oldest are dropped.
 *
 * A window is 60 seconds and a busy service opens thousands of spans in that
 * time, so this is a ring rather than a list that grows until the next flush.
 * Sized well above one window's worth: dropping a slice only costs the label
 * on the samples inside it, which degrades to the "window" correlation the API
 * already models, but dropping them wholesale would make exact correlation
 * quietly stop working under load - the one condition anyone profiles in.
 */
const MAX_SLICES = 20_000;
/**
 * Records which span was executing when, so profile samples can be labelled
 * after the fact.
 *
 * This exists because a JS-only profiler cannot label a sample at the moment it
 * fires. V8 samples on its own thread and hands back a batch afterwards; there
 * is no JS callback to read `AsyncLocalStorage` from. Datadog's profiler solves
 * this with a native addon that writes a thread-local at sample time. Without
 * one, the equivalent is to record the timeline in JS and join it to the
 * samples' timestamps once the batch arrives.
 *
 * The join is only sound because Node runs JS on one thread: at any instant
 * exactly one span's synchronous code is on the stack, so a sample's timestamp
 * identifies it unambiguously. That is a different claim from the time-window
 * overlap the API's honesty rule rejects - overlapping *span durations* say
 * nothing on a concurrent server, because a span's duration includes the awaits
 * during which other requests ran. These are execution slices, not durations.
 *
 * Known limitation, and the reason unattributed samples stay unlabelled rather
 * than being guessed at: while a span awaits, uninstrumented code may run. No
 * slice covers it, so its samples carry no span - which is correct, since that
 * code is in no span - but a sample landing in an outer span's slice while an
 * uninstrumented callback runs is attributed to the outer span. Instrumented
 * work always opens its own slice and is attributed exactly.
 */
export class SpanSliceRecorder {
    slices = [];
    /** Innermost-first stack of spans currently open on this thread. */
    stack = [];
    /**
     * Records that a span began executing.
     *
     * Closes the enclosing span's slice first: from here until this span ends,
     * the innermost thing running is this one, and attributing the interval to
     * both would double-count it.
     */
    enter(traceId, spanId, at = performance.now()) {
        this.closeTop(at);
        this.stack.push({ spanId, traceId, since: at });
    }
    /**
     * Records that a span stopped executing, and resumes the enclosing one.
     *
     * Accepts an absent id because a step whose caller could not be resolved was
     * never entered either: the lookup below simply misses and nothing unwinds.
     */
    exit(spanId, at = performance.now()) {
        const index = this.stack.findIndex((entry) => entry.spanId === spanId);
        if (index === -1) {
            return;
        }
        // Everything above it goes too. A span ending while its children are still
        // open means the children were never awaited - the registry warns about
        // exactly this - and leaving them on the stack would attribute the rest of
        // the process's work to a span that has finished.
        //
        // Unwound innermost-first, advancing each enclosing span to `at` as its
        // child is closed. Without that step the abandoned parent's `since` is
        // still the moment its child started, so it would emit a slice spanning the
        // child's entire execution - the same microseconds counted twice, under two
        // different spans.
        for (let depth = this.stack.length - 1; depth >= index; depth -= 1) {
            const entry = this.stack[depth];
            this.push({
                spanId: entry.spanId,
                traceId: entry.traceId,
                from: entry.since,
                to: at,
            });
            this.stack.pop();
            const enclosing = this.stack[this.stack.length - 1];
            if (enclosing) {
                enclosing.since = at;
            }
        }
    }
    /**
     * Every slice recorded so far, oldest first, with the still-open spans
     * closed at `until` so a window flush does not lose the work in flight.
     */
    drain(until = performance.now()) {
        const open = this.stack.map((entry) => ({
            spanId: entry.spanId,
            traceId: entry.traceId,
            from: entry.since,
            to: until,
        }));
        // The open spans keep running, so their next slice starts where this one
        // ended rather than back at their original entry.
        for (const entry of this.stack) {
            entry.since = until;
        }
        const drained = [...this.slices, ...open].sort((a, b) => a.from - b.from);
        this.slices.length = 0;
        return drained;
    }
    /** Discards everything, for shutdown and for tests. */
    reset() {
        this.slices.length = 0;
        this.stack.length = 0;
    }
    closeTop(at) {
        const top = this.stack[this.stack.length - 1];
        if (!top) {
            return;
        }
        if (at > top.since) {
            this.push({
                spanId: top.spanId,
                traceId: top.traceId,
                from: top.since,
                to: at,
            });
        }
        top.since = at;
    }
    push(slice) {
        if (slice.to <= slice.from) {
            // A slice with no duration cannot contain a sample, and keeping them
            // would fill the ring with the zero-width entries that decorator-heavy
            // code produces on every call.
            return;
        }
        if (this.slices.length >= MAX_SLICES) {
            this.slices.shift();
        }
        this.slices.push(slice);
    }
}
/**
 * The recorder the instrumentation writes to, or null when profiling is off.
 *
 * A module-level handle rather than an injected dependency because the writers
 * are on the hot path - every instrumented method entry and exit - and the
 * overwhelmingly common case is profiling being disabled. That case has to cost
 * one null check, not a resolved provider and a virtual call.
 */
let activeRecorder = null;
export function activeSliceRecorder() {
    return activeRecorder;
}
export function setActiveSliceRecorder(recorder) {
    activeRecorder = recorder;
}
